def pointer_get(doc,pointer):
 value=doc
 for token in pointer.split('/')[1:]:
  token=token.replace('~1','/').replace('~0','~');value=value[int(token)] if isinstance(value,list) else value[token]
 return value

def anchors(paths,tests=False):
 result=[]
 for name in paths:
  p=ROOT/('prototype/tests' if tests else 'prototype/prain')/name
  if not p.exists():continue
  data=p.read_bytes();tree=ast.parse(data)
  for node in ast.walk(tree):
   if isinstance(node,(ast.FunctionDef,ast.ClassDef)) and (not tests or node.name.startswith('test_')):
    result.append({'path':str(p.relative_to(ROOT)),'symbol':node.name,'line':node.lineno,'sha256':SHA(data),'evidence_kind':'SOURCE_ANCHOR_ONLY_NOT_EXECUTION'})
 return result

def main():
 allrows=[json.loads(x) for x in (ROOT/'TRACEABILITY/IMPLEMENTATION_EVIDENCE_20261025/requirement_evidence.jsonl').open()]
 rows=[r for r in allrows if 70<=int(r['requirement_id'][4:])<=1300]
 archivebytes=(ROOT/ARCH).read_bytes();z=zipfile.ZipFile(ROOT/ARCH);reviews={};result=[]
 for row in rows:
  n=int(row['requirement_id'][4:]);s=row['source'];p=ROOT/s['path'];raw=p.read_bytes();assert SHA(raw)==s['sha256'];assert raw.decode().splitlines()[s['line']-1].strip()==row['text']
  canon=s['current_canonical_compatibility'];current=z.read(canon['member']);assert SHA(current)==canon['sha256']
  successor={'archive':ARCH,'archive_sha256':SHA(archivebytes),'member':canon['member'],'sha256':SHA(current),'source_line':s['line'] if raw==current else None}
  if p.suffix=='.json':
   family=p.name.removesuffix('.schema.json');intent,codepaths,testpaths,missing=FAMILIES[family];doc=json.loads(raw);canonicaldoc=json.loads(current)
   assert doc==canonicaldoc, 'Need semantic diff review for '+family
   ptr=s['json_pointer_context']['pointer'];value=pointer_get(doc,ptr);successor['json_pointer']=ptr
   segments=ptr.split('/')[1:];group='/'+'/'.join(segments[:2]) if segments and segments[0]=='properties' else ('/'+ '/'.join(segments[:2]) if segments and segments[0]=='allOf' else '')
   if not group:group=''
   context=pointer_get(doc,group);constraint={k:v for k,v in context.items() if k in ['type','const','enum','required','additionalProperties','minLength','maxLength','pattern','format','minimum','maximum','minItems','maxItems','uniqueItems','allOf','anyOf']} if isinstance(context,dict) else context
   obligation='canonical:'+family+'#'+group
   # Metadata/description fragments remain preserved context; annotations are
   # never counted as autonomous runtime validation requirements.
   leaf=segments[-1] if segments else '';annotation=leaf in {'title','description'}
   disposition='NON_NORMATIVE' if annotation else 'RETAIN'
   rationale=(('JSON annotation has no validation effect; preserve its intent through the enclosing family, not as a new executable rule. ' if annotation else 'Retain this canonical schema fragment as part of its enclosing whole-schema obligation, not an independent implementation completion. ')+intent+' Exact node '+ptr+' = '+json.dumps(value,ensure_ascii=False,separators=(',',':'))+'.')
   detail={'family':family,'enclosing_pointer':group,'enclosing_constraints':constraint,'node_value_sha256':SHA(json.dumps(value,sort_keys=True,separators=(',',':')).encode()),'json_schema_dialect':'2020-12','whole_schema_review':'REVIEWED_PROPERTY_REQUIREMENTS_CONDITIONALS_AND_PROSE_GUARDS'}
   if family not in reviews:reviews[family]={'canonical':{**successor,'json_pointer':''},'intent':intent,'root_required':doc.get('required',[]),'conditional_guards':doc.get('allOf',[]),'implementation_missing':missing,'partial_code_anchors':anchors(codepaths),'partial_test_anchors':anchors(testpaths,True),'runtime_conformance':'NOT_VERIFIED'}
   code=reviews[family]['partial_code_anchors'];tests=reviews[family]['partial_test_anchors']
  else:
   disposition,rationale,missing=MD[n];obligation='document:'+p.name+':'+str(s['line']);detail={'whole_document_context_reviewed':True,'current_document_changed':raw!=current}
   exact=[i+1 for i,line in enumerate(current.decode().splitlines()) if line.strip()==row['text']];assert exact
   successor['line']=s['line'] if raw==current else exact[0]
   if raw!=current:rationale+=' Whole-document comparison found only explicit Phase0 closure-status updates; this rule remains unchanged and Phase1 authorization remains separate.'
   code=[];tests=[]
  result.append({'requirement_id':row['requirement_id'],'source':{'path':s['path'],'line':s['line'],'sha256':s['sha256'],'text_sha256':row['text_sha256']},'text':row['text'],'disposition':disposition,'rationale':rationale,'canonical_reference':successor,'missing_proof':missing,'effective_disposition':disposition,'reviewer':'normative_a independent source review','review_method':'WHOLE_CONTRACT_AND_CONTEXT_REVIEW_WITH_EXACT_NODE_BINDING','canonical_successor':successor,'normative_obligation_group':obligation,'semantic_rationale':rationale,'context':detail,'partial_implementation_anchors':code,'partial_test_anchors':tests,'implementation_status':('PARTIAL' if code else 'OPEN') if disposition!='NON_NORMATIVE' else 'NOT_APPLICABLE','remaining_proof':missing,'production_acceptance':False})
 assert len(result)==1231 and len({r['requirement_id'] for r in result})==1231
 (OUT/'part_a_reviews.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False,sort_keys=True)+'\n' for r in result))
 (OUT/'part_a_schema_family_reviews.json').write_text(json.dumps(reviews,ensure_ascii=False,indent=2)+'\n')
 summary={'range':['RTM-00070','RTM-01300'],'row_count':len(result),'dispositions':dict(collections.Counter(r['effective_disposition'] for r in result)),'schema_family_reviews':len(reviews),'whole_document_contexts':len({r['source']['path'] for r in result if r['source']['path'].endswith('.md')}),'normative_groups':len({r['normative_obligation_group'] for r in result}),'unresolved_normative_dispositions':sum(r['effective_disposition']=='UNRESOLVED' for r in result),'runtime_requirements_accepted':0,'production_acceptance':False,'method':'Reviewer read whole canonical family requirements/conditionals and prose guard contexts; serialization expands reviewed family/context judgments to exact source IDs and pointers. This is not1231 independently implemented behaviors. Semantic retention does not grant implementation acceptance.','artifacts':{name:SHA((OUT/name).read_bytes()) for name in ['part_a_reviews.jsonl','part_a_schema_family_reviews.json']}}
 (OUT/'part_a_summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(summary,indent=2))
if __name__=='__main__':main()
